/* @lc app=leetcode id=2685 lang=kotlin */
class Solution { fun countCompleteComponents(n: Int, edges: Array<IntArray>): Int = IntArray(n) { it }.let { p -> DeepRecursiveFunction<Int, Int> { i -> if (p[i] == i) i else callRecursive(p[i]).also { p[i] = it } }.let { find -> IntArray(n) { 1 }.let { vCount -> IntArray(n) { 0 }.let { eCount -> edges.map { e -> find.callRecursive(e[0]).let { r1 -> find.callRecursive(e[1]).let { r2 -> if (r1 != r2) p[r1].also { p[r1] = r2 }.also { vCount[r2] += vCount[r1] }.also { eCount[r2] += eCount[r1] } }.run { (eCount[find.callRecursive(e[0])] + 1).also { eCount[find.callRecursive(e[0])] = it } } } }.run { (0 until n).count { i -> p[i] == i && eCount[i] == vCount[i] * (vCount[i] - 1) / 2 } } } } } }